class Solution {
    void dfs(const vector<int>& nums, int i, int curOR, int maxOR, int n, int& count) {
        if (i == n) {
            if (curOR == maxOR) count++;
            return;
        }
        dfs(nums, i + 1, curOR | nums[i], maxOR, n, count);
        dfs(nums, i + 1, curOR, maxOR, n, count);
    }
public:
    int countMaxOrSubsets(vector<int>& nums) {
        int maxOR = 0;
        for (int x : nums) maxOR |= x;
        int n = nums.size();
        int count = 0;
        dfs(nums, 0, 0, maxOR, n, count);
        return count;
    }
};
